rows.forEach((x,i)=>{const len=Math.max(.5,x[mi]/tot*C-3);s+=`<circle data-i="${i}" cx="100" cy="100" r="${r}" fill="none" stroke="${COL[i%8]}" stroke-width="26" stroke-dasharray="${len} ${C-len}" stroke-dashoffset="${-acc}" transform="rotate(-90 100 100)"/>`;acc+=x[mi]/tot*C;
L+=`<li data-i="${i}"><i style="background:${COL[i%8]}"></i><span>${x[0]}</span><em>${(opt.f||nf)(x[mi])}</em><u>${(x[mi]/tot*100).toFixed(1)}%</u></li>`});
