function gauge(el,v,lab,sub){const c=v<50?"#ff6b57":v<90?"#fbbf24":"#4ade80",r=52,C=2*Math.PI*r;el.innerHTML=`<svg viewBox="0 0 140 140"><circle cx="70" cy="70" r="${r}" fill="none" stroke="#2a2d5a" stroke-width="10"/><circle class="gc" cx="70" cy="70" r="${r}" fill="none" stroke="${c}" stroke-width="10" stroke-linecap="round" stroke-dasharray="0 ${C}" data-d="${v/100*C} ${C}" transform="rotate(-90 70 70)" style="transition:stroke-dasharray 1.4s cubic-bezier(.2,.8,.2,1)"/><text class="sg" x="70" y="82" text-anchor="middle">${v}</text></svg><b>${lab}</b><p>${sub}</p>`}
