function cnt(e){const t=+e.dataset.to,d=+e.dataset.d||0,p=e.dataset.p||"",s=e.dataset.s||"",f=v=>p+(d?v.toLocaleString("en-IN",{minimumFractionDigits:d,maximumFractionDigits:d}):nf(v))+s;cancelAnimationFrame(e._r);if(rm){e.textContent=f(t);return}const t0=performance.now();(function st(n){const k=Math.min(1,(n-t0)/1500);e.textContent=f(t*(1-Math.pow(1-k,3)));if(k<1)e._r=requestAnimationFrame(st)})(t0)}
$$('#pt2 button').forEach(b=>b.onclick=()=>{$$('#pt2 button').forEach(x=>x.setAttribute('aria-pressed',x===b));['se','pa','au'].forEach(k=>$('#p-'+k).classList.toggle('on',k==b.dataset.t));$$('#p-'+b.dataset.t+' [data-to]').forEach(cnt)});
const io=new IntersectionObserver(es=>es.forEach(x=>{if(!x.isIntersecting)return;const t=x.target;t.classList.add('in');if(t.dataset.to)cnt(t);if(t.dataset.w)t.style.width=t.dataset.w+'%';if(t.classList.contains('gc'))t.setAttribute('stroke-dasharray',t.dataset.d);io.unobserve(t)}),{threshold:.2});
$$('.rv,[data-to],[data-w],.gc').forEach(e=>io.observe(e));
