$$('#fl,.orb').forEach(e=>so.observe(e));
function upd(){PINS.forEach(o=>o.u());if(hero.classList.contains('go')){const hr=hero.getBoundingClientRect();if(hr.bottom<-60){if(!hv.paused)hv.pause()}else if(hr.bottom>0&&hv.paused&&!hv.ended&&!hero.classList.contains('np'))hv.play().catch(()=>{})}const vh=innerHeight;document.documentElement.style.setProperty('--hs',clamp(scrollY/vh).toFixed(4));if(rm){$$('.nd').forEach(n=>n.classList.add('on'));return}
act.forEach(el=>{const r=el.getBoundingClientRect(),c=(r.top+r.height/2)/vh,e=clamp((1.05-c)/.45),x=clamp((.38-c)/.38),p=clamp((vh-r.top)/(vh+r.height));el.style.setProperty('--e',e.toFixed(3));el.style.setProperty('--x',x.toFixed(3));el.style.setProperty('--p',p.toFixed(3));if(el.id=='fl'){const q=clamp((vh*.9-r.top)/(vh*.55));el.style.setProperty('--e',q.toFixed(3));$$('.nd').forEach((n,i)=>n.classList.toggle('on',q>(i+.4)/6))}})}
let tk=0;addEventListener('scroll',()=>{if(!tk){tk=1;requestAnimationFrame(()=>{tk=0;upd()})}},{passive:true});addEventListener('resize',upd);upd();setTimeout(upd,400);
/* 3D tilt on pointer (delegated, unthrottled 35-element loop eliminated) */
if(fine&&!rm){
  let activeTilt=null;
  document.addEventListener('pointerover',e=>{activeTilt=e.target.closest&&e.target.closest('[data-tilt],.tl3')},{passive:true});
  document.addEventListener('pointerout',e=>{if(activeTilt&&!activeTilt.contains(e.relatedTarget)){activeTilt.style.removeProperty('--ty');activeTilt.style.removeProperty('--tx');activeTilt=null}},{passive:true});
  document.addEventListener('pointermove',e=>{if(!activeTilt)return;const r=activeTilt.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5,k=activeTilt.classList.contains('tl3')?14:7;activeTilt.style.setProperty('--ty',(x*k).toFixed(2)+'deg');activeTilt.style.setProperty('--tx',(-y*k).toFixed(2)+'deg');activeTilt.style.setProperty('--gx',((x+.5)*100).toFixed(1)+'%');activeTilt.style.setProperty('--gy',((y+.5)*100).toFixed(1)+'%')},{passive:true});
}
