const ft=$('#ft');function posFt(x,y){const fw=ft.offsetWidth||200,fh=ft.offsetHeight||40,tx=(x+16+fw>innerWidth-12)?Math.max(12,x-fw-16):x+16,ty=(y+16+fh>innerHeight-12)?Math.max(12,y-fh-16):y+16;ft.style.transform=`translate(${tx.toFixed(1)}px,${ty.toFixed(1)}px)`}
document.addEventListener('mouseover',e=>{const t=e.target.closest&&e.target.closest('[data-tip]');if(t){ft.textContent=t.dataset.tip;ft.classList.add('on')}else ft.classList.remove('on')});
